// Chỉ bộ gắn nhỏ được tải lúc vào trang. Engine/SVG tải khi phần giải thích xuất hiện.
import {escapeHTML as esc} from './math-ui.js';
let counter=0,contexts=new Map(),generation=0,widgets=new Set(),environment={getState:()=>({}),save:()=>{}};
export function configureVisuals(options){environment=options}
export function resetVisuals(){generation++;for(let w of widgets)w.stop();widgets.clear();contexts.clear()}
export function visualSlot(q,ctx={}){let id='visual-'+(++counter);contexts.set(id,{q,ctx});return `<section class="network-visual ${ctx.deep?'vis-deep':'vis-brief'}" data-visual="${id}" tabindex="0" aria-label="Minh họa cho câu ${esc(q.id)}"><p class="muted">Đang chuẩn bị minh họa cho câu này…</p></section>`}
export function cleanVisuals(raw){let out={};if(!raw||typeof raw!=='object'||Array.isArray(raw))return out;for(let [key,row] of Object.entries(raw).slice(-150)){if(['__proto__','constructor','prototype'].includes(key)||key.length>240||!row||!Number.isInteger(row.step)||row.step<0||row.step>200)continue;let params;try{let text=JSON.stringify(row.params||{});if(text.length>5000||/__proto__|constructor|prototype/.test(text))continue;params=JSON.parse(text)}catch{continue}out[key]={step:row.step,speed:[.5,1,2].includes(row.speed)?row.speed:1,params}}return out}
export async function mountVisuals(root=document){let ownGeneration=generation,targets=[...root.querySelectorAll('[data-visual]')].filter(el=>!el.dataset.mounted);if(!targets.length)return;let [specs,models,renderer,math]=await Promise.all([import('./visual-specs.js'),import('./visual-models.js'),import('./visual-render.js'),import('./math-reference.js')]);if(ownGeneration!==generation)return;for(let el of targets){let context=contexts.get(el.dataset.visual);if(!context||!el.isConnected)continue;el.dataset.mounted='true';try{let {q,ctx}=context,baseSpec=specs.deriveSpec(q,ctx);if(ctx.generated&&!ctx.transfer){let g=math.generateProblem(ctx.generated.family,ctx.generated.seed);baseSpec=specs.generatedSpec(g.family,g.params)}let base=models.buildSimulation(baseSpec),state=environment.getState(),key=ctx.key||q.id+':'+(ctx.deep?'deep':'brief'),remember=state.visuals?.[key],model=base;
 if(remember)try{model=models.buildSimulation({...baseSpec,params:{...baseSpec.params,...remember.params}})}catch{model=base}
 let conclusion=model.type==='queue'?model.steps.length-2:model.type==='encapsulation'?3:model.steps.length-1;let initial=ctx.mode==='unknown'?0:ctx.mode==='wrong'?Math.min(model.steps.length-1,model.type==='tcp'?4:model.type==='subnet'?1:0):conclusion,index=remember?Math.min(remember.step,model.steps.length-1):initial,speed=remember?.speed||1,timer=null,error='',sandbox=!!remember&&JSON.stringify(model.params)!==JSON.stringify(base.params),motion=()=>environment.getState().settings?.motion!==false&&!globalThis.matchMedia?.('(prefers-reduced-motion: reduce)').matches;
 const stop=()=>{if(timer!==null)clearInterval(timer);timer=null},persist=()=>{let s=environment.getState();s.visuals??={};s.visuals[key]={step:index,speed,params:model.params};let keys=Object.keys(s.visuals);for(let k of keys.slice(0,Math.max(0,keys.length-150)))delete s.visuals[k];environment.save()};let widget={stop};widgets.add(widget);
 function draw(){let focused=el.contains(document.activeElement)?document.activeElement?.dataset?.visAction:null,frame=model.steps[index];el.innerHTML=`<div class="vis-title"><span class="vis-seal" aria-hidden="true">葉</span><div><strong>${esc(model.title)}</strong><small>${ctx.transfer||ctx.generated||!baseSpec.illustrative?'Dữ kiện gắn với câu đang học':'Ví dụ đơn giản tự tạo theo chủ đề'}</small></div><span class="vis-step">${index+1}/${model.steps.length}</span></div>${sandbox?'<p class="vis-sandbox">Đang thử tham số khác. Đáp án và tiến độ câu gốc giữ nguyên.</p>':''}${ctx.mode==='wrong'?`<aside class="vis-error"><strong>Điểm cần sửa</strong><p>${esc(ctx.selectedText?'Bạn chọn: '+ctx.selectedText+'. ':'')}${esc(ctx.issue||'Chỉ từ đáp số cuối chưa xác định được bước sai. Chạy từng bước để đối chiếu dữ kiện, đơn vị và công thức.')}</p></aside>`:ctx.mode==='unknown'?'<p class="vis-intro">Bắt đầu từ bước đầu. Bấm “Từng bước” để quan sát một thay đổi mỗi lần.</p>':''}${frame.scene?.kind==='sequence'&&frame.scene.events.length>6?'<p class="muted">Sơ đồ giữ 6 sự kiện gần nhất. Dùng “Làm lại” và “Từng bước” để xem toàn bộ trình tự.</p>':''}<div class="vis-picture" aria-label="Sơ đồ có thể cuộn ngang">${renderer.renderScene(frame.scene,model.title+' · '+frame.text)}</div><p class="vis-caption" aria-live="polite" aria-atomic="true"><b>Bước ${index+1}:</b> ${esc(frame.text)}</p><div class="vis-controls"><button type="button" class="secondary" data-vis-action="play" ${!motion()?'disabled':''}>Chạy</button><button type="button" class="secondary" data-vis-action="pause" ${timer===null?'disabled':''}>Tạm dừng</button><button type="button" class="secondary" data-vis-action="step" ${index>=model.steps.length-1?'disabled':''}>Từng bước</button><button type="button" class="secondary" data-vis-action="reset">Làm lại</button><label>Tốc độ<select data-vis-speed aria-label="Tốc độ mô phỏng">${[.5,1,2].map(v=>`<option value="${v}" ${speed===v?'selected':''}>${v}×</option>`).join('')}</select></label></div>${!motion()?'<p class="muted">Đang tắt chuyển động: dùng hình tĩnh, “Từng bước” và mô tả ở trên.</p>':''}<details class="vis-more" ${ctx.deep?'open':''}><summary>Dữ kiện, bảng trạng thái & mô hình đầy đủ</summary>${renderer.renderTable(frame.table)}<p><strong>Kết nối với câu này:</strong> ${esc(ctx.stageLabel?ctx.stageLabel+'. ':'')}${esc(ctx.answerText||q.options?.[q.correct]||q.worked?.result||'Xem lời giải bên cạnh.')} ${esc(ctx.transfer?'Bài tương tự có dữ kiện riêng, không dùng lại đáp số bài mẫu.':q.explain||'')}</p><p class="vis-notes">${esc(model.notes)}</p>${baseSpec.params?.example?'<p>Đề chỉ cho prefix nên địa chỉ IP trong hình được thêm để minh họa, không phải dữ kiện gốc.</p>':''}${model.fields.length?`<form class="vis-params"><h4>Tự thử tham số hợp lệ</h4><div class="fields">${model.fields.map(field=>`<label>${esc(field.label)}${field.type==='select'?`<select name="${field.name}">${field.values.map(v=>`<option value="${esc(v)}" ${field.value===v?'selected':''}>${esc(v)}</option>`).join('')}</select>`:`<input name="${field.name}" type="${field.type||'number'}" value="${esc(field.value)}" ${field.type==='text'?'maxlength="500"':`min="${field.min}" max="${field.max}" step="${field.step}"`} required>`}</label>`).join('')}</div><div class="actions"><button type="submit" class="secondary">Áp dụng để quan sát</button><button type="button" class="secondary" data-vis-action="original">Khôi phục dữ kiện câu</button></div><p class="muted">Đổi tham số ở đây chỉ để khám phá, không thay đáp án hoặc kết quả chấm.</p></form>`:''}<p class="source">Nguồn cơ chế: <a href="sources/${esc(q.sourceFile||['MMT-Chuong1-v2.pdf','MMT-Chuong2-v2.pdf','MMT-Chuong3-v2.pdf','MMT-Chuong4-V2.pdf'][q.ch])}#page=${q.pages?.[0]||1}" target="_blank" rel="noopener">${esc(q.sourceFile||'PDF chương '+(q.ch+1))} · trang PDF ${(q.pages||[1,1]).join('–')}</a>. Hình do website tự biên soạn; không phải hình trích nguyên văn.</p></details>${error?`<p class="error" role="alert">${esc(error)}</p>`:''}`;
 for(let b of el.querySelectorAll('[data-vis-action]'))b.onclick=()=>act(b.dataset.visAction);el.querySelector('[data-vis-speed]').onchange=e=>{speed=Number(e.currentTarget.value);let playing=timer!==null;stop();if(playing)play();persist();draw()};let form=el.querySelector('.vis-params');if(form)form.onsubmit=e=>{e.preventDefault();try{let params={...model.params};for(let field of model.fields){let raw=form.elements.namedItem(field.name).value;if(/^rate\d$/.test(field.name)){params.rates=[...params.rates];params.rates[Number(field.name.slice(4))]=Number(raw)}else if(field.name==='words'){if(!/^[0-9a-fA-F\s]+$/.test(raw)||raw.trim().split(/\s+/).some(w=>w.length>4))throw Error('Word hex 0000–FFFF, cách bằng dấu cách.');params.words=raw.trim().split(/\s+/).map(w=>parseInt(w,16))}else if(field.name==='edges'){params.edges=raw.split(',').map(x=>{let m=x.trim().match(/^([a-zA-Z0-9]{1,12})-([a-zA-Z0-9]{1,12}):(\d+(?:\.\d+)?)$/);if(!m)throw Error('Cạnh dạng u-v:2,v-z:1.');return [m[1],m[2],Number(m[3])]})}else params[field.name]=field.type==='number'?Number(raw):raw}let next=models.buildSimulation({...baseSpec,params});stop();model=next;index=0;sandbox=JSON.stringify(model.params)!==JSON.stringify(base.params);error='';persist();draw()}catch(err){error=err.message;let msg=el.querySelector('[role=alert]');if(!msg){msg=document.createElement('p');msg.className='error';msg.setAttribute('role','alert');el.append(msg)}msg.textContent=error}};if(focused)el.querySelector(`[data-vis-action="${focused}"]`)?.focus()}
 function play(){if(!motion())return;stop();if(index>=model.steps.length-1)index=0;timer=setInterval(()=>{if(!el.isConnected||ownGeneration!==generation||!motion()){stop();return}if(index<model.steps.length-1)index++;if(index>=model.steps.length-1)stop();persist();draw()},1200/speed);timer.unref?.()}
 function act(action){error='';if(action==='play')play();else {stop();if(action==='step')index=Math.min(index+1,model.steps.length-1);if(action==='reset')index=0;if(action==='original'){model=base;index=0;sandbox=false}}persist();draw()}
 el.onkeydown=e=>{e.stopPropagation();if(/INPUT|SELECT|TEXTAREA|BUTTON/.test(e.target.tagName)||e.altKey||e.ctrlKey||e.metaKey)return;if(e.key==='ArrowRight'){e.preventDefault();e.stopPropagation();act('step')}else if(e.key==='Home'){e.preventDefault();e.stopPropagation();act('reset')}else if(e.key===' '){e.preventDefault();e.stopPropagation();act(timer===null?'play':'pause')}};el.onfocusout=()=>{};draw();
 }catch(err){el.innerHTML=`<p class="error">Chưa dựng được minh họa này: ${esc(err.message)}. Bạn vẫn có thể học bằng lời giải và PDF.</p>`}}
}
